<?php
declare(strict_types=1);
namespace App\Application\QuestionBank\Service;
use App\Application\QuestionBank\DTO\Request\CommitQuestionImportRequestDto;use App\Application\QuestionBank\DTO\Response\CommitQuestionImportResponseDto;use App\Application\QuestionBank\Port\TransactionManagerInterface;use App\Domain\QuestionBank\Repository\ImportedQuestionWriterInterface;use App\Domain\QuestionBank\Repository\QuestionImportRepositoryInterface;
final class CommitQuestionImportService { public function __construct(private readonly QuestionImportRepositoryInterface $imports,private readonly ImportedQuestionWriterInterface $questions,private readonly TransactionManagerInterface $transactions){} public function commit(CommitQuestionImportRequestDto $r):CommitQuestionImportResponseDto{return $this->transactions->transactional(function()use($r){$i=$this->imports->findByIdForUser($r->importId,$r->userId);if($i===null)throw new \DomainException('Importacao nao encontrada.');if($i->status!=='VALIDATED')throw new \DomainException('Importacao ja foi confirmada.');$rows=array_map(static fn($x)=>$x->payload,array_filter($i->rows,static fn($x)=>$x->valid));$n=$this->questions->createFromImport($r->syllabusId,$r->userId,$rows);$this->imports->markCommitted($i->id);return new CommitQuestionImportResponseDto($i->id,$n);});}}
